const response = $input.first().json;
const patient = Array.isArray(response) ? response[0] : response;
if (!patient || !patient.id) { throw new Error('Upsert Patient failed — no id returned. Check Supabase headers and ch_patients table.'); }
return [{ json: { patient_id: patient.id } }];

const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const _ins = $('Insert Intake').first().json;
const _row = Array.isArray(_ins) ? _ins[0] : _ins;
if (!_row || !_row.id) return [];
const name = $('Set Fields').first().json.patient_name;
const email = $('Set Fields').first().json.patient_email;
const service = $('Parse Deepseek Response').first().json.service_category;
const urgency = $('Parse Deepseek Response').first().json.urgency_level;

const messages = {
  3: {
    headline: 'Your case has been flagged as urgent',
    body: 'Our team has been notified and will contact you as soon as possible — typically within the hour during clinic hours.',
    icon: '🚨'
  },
  2: {
    headline: 'Your case has been prioritized',
    body: 'We will review your request and be in touch within 1 business day to schedule your consultation.',
    icon: '⚡'
  },
  1: {
    headline: 'Your request is confirmed',
    body: 'We will be in touch within 1–2 business days to schedule your appointment at a time that works for you.',
    icon: '✅'
  }
};
const m = messages[urgency] || messages[1];

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:#eef2ff;font-family:Arial,sans-serif">
<table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:32px 16px">
<table width="600" cellpadding="0" cellspacing="0" style="max-width:600px">
<tr><td style="padding-bottom:20px;text-align:center">
<img src="https://mjfvjogsknnuizsoygpp.supabase.co/storage/v1/object/public/assets/cedar-healthcare-logo.png" alt="Cedar Healthcare" style="max-height:24px">
</td></tr>
<tr><td style="background:linear-gradient(135deg,#1d40ae,#06b6d4);border-radius:16px 16px 0 0;padding:40px 32px;text-align:center">
<p style="margin:0 0 8px;font-size:28px;font-weight:800;color:#fff">Message Received</p>
<p style="margin:0;font-size:15px;color:rgba(255,255,255,0.8)">Cedar Healthcare · Austin, Texas</p>
</td></tr>
<tr><td style="background:#fff;padding:40px 36px">
<p style="margin:0 0 16px;font-size:16px;color:#374151;line-height:1.7">Hi <strong style="color:#1d40ae">${esc(name)}</strong>,</p>
<p style="margin:0 0 28px;font-size:15px;color:#374151;line-height:1.8">Thank you for reaching out to Cedar Healthcare. We have received your message and a member of our team will be in touch with you shortly.</p>
<table width="100%" cellpadding="0" cellspacing="0" style="background:linear-gradient(135deg,#eff6ff,#ecfeff);border:1px solid #bae6fd;border-radius:12px;margin-bottom:28px">
<tr><td style="padding:28px;text-align:center">
<p style="margin:0 0 10px;font-size:36px">${m.icon}</p>
<p style="margin:0 0 8px;font-size:17px;font-weight:700;color:#1d40ae">${m.headline}</p>
<p style="margin:0;font-size:14px;color:#374151;line-height:1.7">${m.body}</p>
<p style="margin:12px 0 0;font-size:13px;color:#6366f1;font-weight:600">Your request: ${esc(service)}</p>
</td></tr></table>
<table width="100%" cellpadding="0" cellspacing="0" style="background:#fef2f2;border:1px solid #fecaca;border-radius:10px;margin-bottom:36px">
<tr><td style="padding:16px 20px;font-size:14px;color:#7f1d1d;line-height:1.6">⚠️ If you are experiencing a medical emergency, please call <strong>911</strong> immediately.</td></tr></table>
