</td></tr>
<tr><td style="background:linear-gradient(135deg,#1d40ae,#06b6d4);border-radius:0 0 16px 16px;padding:20px;text-align:center">
<p style="margin:0;font-size:12px;color:rgba(255,255,255,0.7)">Cedar Healthcare · Austin, Texas · This is an automated confirmation</p>
</td></tr>
</table></td></tr></table>
</body></html>`;

return [{ json: { to: email, from: 'Cedar Healthcare <intake@mail.mcruz-portfolio.space>', subject: 'We received your request — Cedar Healthcare', html } }];

const raw = $input.first().json;
const pd  = $('Set Fields').first().json;

// Everything the model returns is treated as data to be validated, not as a
// precondition. Until 2026-08-08 each of the checks below was a `throw`, and a throw
// here ends the run: no ch_intake_requests row, no practitioner alert, HTTP 500 to
// Tally, and a patient's message gone. A model that answers badly must not be able to
// delete an intake. Carried from Brasa's item 11.
let modelFailed = null;   // null = the model answered usably
let ai = {};

const txt = raw.choices?.[0]?.message?.content;
if (typeof txt !== 'string' || !txt.trim()) {
  modelFailed = 'the model returned no content';
} else {
  const cleaned = txt.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  try { ai = JSON.parse(cleaned); }
  catch (e) { modelFailed = 'the model returned text that is not JSON'; ai = {}; }
}

const req = ['service_category','urgency_level','complexity','recommended_action','confidence_flag'];
if (!modelFailed) {
  const missing = req.filter(k => ai[k] === undefined);
  if (missing.length) modelFailed = 'the model omitted ' + missing.join(', ');
}

// Urgency is repaired rather than rejected, and upwards. Cedar bands alerts by this
// number and alerts on every level (ADR-2), so an unknown urgency becoming 3 changes
// how urgently someone is told, never whether. It over-bands on a provider fault, and
// that is the cheaper direction to be wrong in for a clinic.
if (!modelFailed && ![1,2,3].includes(ai.urgency_level)) {
  modelFailed = 'the model returned urgency_level ' + JSON.stringify(ai.urgency_level);
}
if (modelFailed) {
  ai = { service_category: null, urgency_level: 3, complexity: 'high',
         recommended_action: 'Not triaged by the classifier — ' + modelFailed
                           + '. A human needs to read this intake.',
         confidence_flag: true };
}

const svc = $('Fetch Services').all().map(i => i.json);
const SERVICES = svc.map(s => s.name);
const FALLBACK = (svc.find(s => !s.assignable) || {}).name;
if (!SERVICES.length) throw new Error('ch_services returned no rows - cannot validate service_category');
if (!FALLBACK) throw new Error('ch_services has no non-assignable fallback category');

const COMPLEXITY = ['high','medium','low'];

let degraded = false;
if (!SERVICES.includes(ai.service_category)) { ai.service_category = FALLBACK; degraded = true; }
if (!COMPLEXITY.includes(ai.complexity))     { ai.complexity       = 'medium'; degraded = true; }
if (typeof ai.confidence_flag !== 'boolean') { ai.confidence_flag  = true;     degraded = true; }

if (degraded) ai.confidence_flag = true;

if (ai.service_category === FALLBACK) ai.confidence_flag = true;

return [{ json: {
  patient_name:       pd.patient_name,
  patient_email:      pd.patient_email,
  patient_phone:      pd.patient_phone,
  raw_message:        pd.raw_message,
  service_category:   ai.service_category,
  urgency_level:      ai.urgency_level,
  complexity:         ai.complexity,
  recommended_action: ai.recommended_action,
  needs_review:       ai.confidence_flag,
  model_failed:       modelFailed
} }];

const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const _ins = $('Insert Intake').first().json;
const _row = Array.isArray(_ins) ? _ins[0] : _ins;
if (!_row || !_row.id) return [];
const name = $('Set Fields').first().json.patient_name;
const email = $('Set Fields').first().json.patient_email;
const phone = $('Set Fields').first().json.patient_phone;
const message = $('Set Fields').first().json.raw_message;
const service = $('Parse Deepseek Response').first().json.service_category;
const action = $('Parse Deepseek Response').first().json.recommended_action;
const complexity = $('Parse Deepseek Response').first().json.complexity;
const urgency = $('Parse Deepseek Response').first().json.urgency_level;

const r0 = $('Insert Intake').first().json;
const row = Array.isArray(r0) ? r0[0] : r0;
const rec = row && row.ch_practitioners ? row.ch_practitioners : null;
const prac = {
  name: rec ? rec.full_name : 'Cedar Healthcare Team',
  email: 'mcruzcardoza@gmail.com'
};

const urgencyConfig = {
  3: { label: 'Level 3 — Acute',   description: 'Patient reports active pain or functional impairment. Requires same-day contact.', badgeColor: '#dc2626', badgeBg: '#fef2f2', headerBadge: '🚨 URGENT ALERT',   subject: '🚨 URGENT — New intake (Level 3 Acute): ' + name },
  2: { label: 'Level 2 — Ongoing', description: 'Recurring or worsening condition. Requires follow-up within 1 business day.',     badgeColor: '#d97706', badgeBg: '#fffbeb', headerBadge: '⚠️ PRIORITY INTAKE', subject: '⚠️ New intake (Level 2 Ongoing): ' + name },
  1: { label: 'Level 1 — Routine', description: 'General enquiry or routine appointment request. Standard scheduling applies.',   badgeColor: '#059669', badgeBg: '#f0fdf4', headerBadge: '📋 NEW INTAKE',     subject: '📋 New intake (Level 1 Routine): ' + name }
};
const u = urgencyConfig[urgency] || urgencyConfig[1];

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:#eef2ff;font-family:Arial,sans-serif">
<table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:32px 16px">
<table width="600" cellpadding="0" cellspacing="0" style="max-width:600px">
<tr><td style="padding-bottom:20px;text-align:center">
<img src="https://mjfvjogsknnuizsoygpp.supabase.co/storage/v1/object/public/assets/cedar-healthcare-logo.png" alt="Cedar Healthcare" style="max-height:24px">
</td></tr>
<tr><td style="background:linear-gradient(135deg,#1d40ae,#06b6d4);border-radius:16px 16px 0 0;padding:32px;text-align:center">
<div style="display:inline-block;background:rgba(255,255,255,0.2);border:1px solid rgba(255,255,255,0.4);border-radius:100px;padding:8px 20px;font-size:12px;font-weight:700;color:#fff;letter-spacing:2px">${u.headerBadge}</div>
<p style="margin:12px 0 0;font-size:24px;font-weight:800;color:#fff">New Patient Intake</p>
<p style="margin:6px 0 0;font-size:14px;color:rgba(255,255,255,0.75)">Assigned to: ${esc(prac.name)}</p>
</td></tr>
<tr><td style="background:#fff;padding:32px">
<table width="100%" cellpadding="0" cellspacing="0" style="background:${u.badgeBg};border-left:4px solid ${u.badgeColor};border-radius:8px;margin-bottom:24px">
<tr><td style="padding:16px 20px">
<p style="margin:0 0 4px;font-size:13px;font-weight:700;color:${u.badgeColor};text-transform:uppercase">${u.label}</p>
<p style="margin:0;font-size:14px;color:#374151">${u.description}</p>
</td></tr></table>
<p style="margin:0 0 12px;font-size:11px;font-weight:700;color:#06b6d4;text-transform:uppercase;letter-spacing:2px">Patient Information</p>
<table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e8eeff;border-radius:10px;margin-bottom:24px">
<tr style="background:#f8faff"><td style="padding:12px 16px;font-size:13px;color:#6b7280;width:35%;border-bottom:1px solid #e8eeff">Name</td><td style="padding:12px 16px;font-size:14px;font-weight:700;color:#111827;border-bottom:1px solid #e8eeff">${esc(name)}</td></tr>
<tr><td style="padding:12px 16px;font-size:13px;color:#6b7280;border-bottom:1px solid #e8eeff">Email</td><td style="padding:12px 16px;font-size:14px;color:#1d40ae;border-bottom:1px solid #e8eeff">${esc(email)}</td></tr>
<tr style="background:#f8faff"><td style="padding:12px 16px;font-size:13px;color:#6b7280;border-bottom:1px solid #e8eeff">Phone</td><td style="padding:12px 16px;font-size:14px;color:#111827;border-bottom:1px solid #e8eeff">${esc(phone || 'Not provided')}</td></tr>
<tr><td style="padding:12px 16px;font-size:13px;color:#6b7280;border-bottom:1px solid #e8eeff">Service</td><td style="padding:12px 16px;font-size:14px;font-weight:700;color:#1d40ae;border-bottom:1px solid #e8eeff">${esc(service)}</td></tr>
<tr style="background:#f8faff"><td style="padding:12px 16px;font-size:13px;color:#6b7280">Complexity</td><td style="padding:12px 16px;font-size:14px;color:#111827">${esc(complexity)}</td></tr>
</table>
<p style="margin:0 0 12px;font-size:11px;font-weight:700;color:#06b6d4;text-transform:uppercase;letter-spacing:2px">Patient Message</p>
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f8faff;border:1px solid #e8eeff;border-radius:10px;margin-bottom:24px">
<tr><td style="padding:20px;font-size:14px;color:#374151;line-height:1.8">${esc(message)}</td></tr></table>
<p style="margin:0 0 12px;font-size:11px;font-weight:700;color:#06b6d4;text-transform:uppercase;letter-spacing:2px">Recommended Action</p>
<table width="100%" cellpadding="0" cellspacing="0" style="background:linear-gradient(135deg,#eff6ff,#ecfeff);border-left:4px solid #06b6d4;border-radius:8px">
<tr><td style="padding:20px;font-size:15px;font-weight:600;color:#1d40ae;line-height:1.7">${esc(action)}</td></tr></table>
</td></tr>
<tr><td style="background:linear-gradient(135deg,#1d40ae,#06b6d4);border-radius:0 0 16px 16px;padding:20px;text-align:center">
<p style="margin:0;font-size:12px;color:rgba(255,255,255,0.7)">Cedar Healthcare Intake System · Austin, Texas</p>
</td></tr>
</table></td></tr></table>
</body></html>`;

return [{ json: { to: prac.email, from: 'Cedar Healthcare <intake@mail.mcruz-portfolio.space>', subject: u.subject, html } }];

const service = $('Parse Deepseek Response').first().json.service_category;

const list = $input.all().map(i => i.json);

const match = list.find(p => p.role === service);

return [{ json: {
  patient_id: $('Extract Patient ID').first().json.patient_id,
  practitioner_id: match ? match.id : null,
  practitioner_name: match ? match.full_name : `Unassigned - no practitioner for "${service}"`
} }];

